//! Media here is generated by FFmpeg, independently of the detector. Run explicitly
//! with REX_TEST_FFMPEG=/path/to/ffmpeg and REX_TEST_FONT=/path/to/a/TrueType/font:
//! cargo test --manifest-path rust/Cargo.toml runtime::markers::tests -- --ignored
use super::*;
use std::path::PathBuf;

struct Fixture { root: PathBuf, ffmpeg: PathBuf }
impl Fixture {
    fn new() -> Self {
        let ffmpeg = PathBuf::from(std::env::var_os("REX_TEST_FFMPEG").expect("set REX_TEST_FFMPEG explicitly"));
        let root = std::env::temp_dir().join(format!("rex-markers-{}-{}", std::process::id(), std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_nanos()));
        std::fs::create_dir_all(&root).unwrap();
        Self { root, ffmpeg }
    }
    fn generate(&self, name: &str, args: &[&str]) -> PathBuf {
        let path = self.root.join(name);
        let status = Command::new(&self.ffmpeg).args(["-hide_banner", "-loglevel", "error", "-nostdin", "-y"])
            .args(args).args(["-threads", "1", "-c:v", "ffv1"]).arg(&path).status().unwrap();
        assert!(status.success(), "independent FFmpeg fixture generation failed");
        path
    }
    fn input(&self, name: &str, path: &Path, duration_ms: i64, video: bool, audio: bool) -> analysis::Input {
        analysis::Input { key: name.into(), part_id: format!("part-{name}"), url: path.to_str().unwrap().into(), auth: None,
            duration_ms, video_index: video.then_some(0), audio_index: audio.then_some(if video { 1 } else { 0 }), chapters: vec![], group: Some("source-season-42".into()) }
    }
}
impl Drop for Fixture { fn drop(&mut self) { let _ = std::fs::remove_dir_all(&self.root); } }
fn marker(row: &ResultRow, kind: &str) -> (i64, i64) {
    let value = row.markers.iter().find(|m| m["type"] == kind).expect("expected content-derived marker");
    (value["startTimeOffset"].as_i64().unwrap(), value["endTimeOffset"].as_i64().unwrap())
}
fn valid(rows: &[ResultRow], duration: i64) {
    for row in rows { for value in &row.markers {
        let a = value["startTimeOffset"].as_i64().unwrap();
        let b = value["endTimeOffset"].as_i64().unwrap();
        assert!(0 <= a && a < b && b <= duration, "invalid marker {value}");
    }}
}

#[test]
#[ignore = "generates real media with explicitly configured FFmpeg"]
fn shared_picture_intro_tracks_different_cold_opens_without_audio() {
    let f = Fixture::new();
    let mut inputs = Vec::new();
    for (name, offset, color) in [("one", 3, "blue"), ("two", 9, "red")] {
        let prefix = format!("color={color}:s=160x90:r=8:d={offset}");
        let suffix = format!("color={color}:s=160x90:r=8:d={}", 40 - offset - 16);
        let path = f.generate(&format!("{name}.mkv"), &["-f", "lavfi", "-i", &prefix, "-f", "lavfi", "-i", "testsrc2=s=160x90:r=8:d=16", "-f", "lavfi", "-i", &suffix,
            "-filter_complex", "[0:v][1:v][2:v]concat=n=3:v=1:a=0[v]", "-map", "[v]"]);
        inputs.push(f.input(name, &path, 40_000, true, false));
    }
    let rows = analyze(&f.ffmpeg, &inputs).unwrap();
    for (row, offset) in rows.iter().zip([3000i64, 9000]) {
        let (a, b) = marker(row, "intro");
        assert!((a - offset).abs() <= 1000, "wrong intro start: {a}");
        assert!((b - offset - 16_000).abs() <= 1000, "wrong intro end: {b}");
    }
    valid(&rows, 40_000);
    inputs[1].group = Some("another-source-season".into());
    assert!(analyze(&f.ffmpeg, &inputs).unwrap().iter().all(|r| !r.markers.iter().any(|m| m["type"] == "intro")));
}

#[test]
#[ignore = "generates real media with explicitly configured FFmpeg"]
fn unrelated_picture_silence_and_steady_tone_do_not_create_intros() {
    let f = Fixture::new();
    let mut inputs = Vec::new();
    for (name, source) in [("noise", "testsrc2=s=160x90:r=8:d=24"), ("other", "smptebars=s=160x90:r=8:d=24")] {
        let path = f.generate(&format!("{name}.mkv"), &["-f", "lavfi", "-i", source, "-f", "lavfi", "-i", "anullsrc=r=2000:cl=mono", "-t", "24", "-c:a", "pcm_s16le"]);
        inputs.push(f.input(name, &path, 24_000, true, true));
    }
    for name in ["tone-one", "tone-two"] {
        let path = f.generate(&format!("{name}.mkv"), &["-f", "lavfi", "-i", "sine=frequency=440:sample_rate=2000:duration=24", "-c:a", "pcm_s16le"]);
        inputs.push(f.input(name, &path, 24_000, false, true));
    }
    let rows = analyze(&f.ffmpeg, &inputs).unwrap();
    assert!(rows.iter().all(|r| r.markers.is_empty()), "unrelated/static/silent media must not acquire markers");
}

#[test]
#[ignore = "generates real audio with explicitly configured FFmpeg"]
fn shared_changing_audio_tracks_offsets_without_video() {
    let f = Fixture::new();
    let mut inputs = Vec::new();
    for (name, offset) in [("audio-one", 2), ("audio-two", 6)] {
        let prefix = format!("anullsrc=r=2000:cl=mono:d={offset}");
        let suffix = format!("anullsrc=r=2000:cl=mono:d={}", 30 - offset - 16);
        let path = f.generate(&format!("{name}.mkv"), &["-f", "lavfi", "-i", &prefix,
            "-f", "lavfi", "-i", "aevalsrc=0.4*sin(2*PI*(130+55*mod(floor(t*2)\\,12))*t):s=2000:d=16",
            "-f", "lavfi", "-i", &suffix, "-filter_complex", "[0:a][1:a][2:a]concat=n=3:v=0:a=1[a]",
            "-map", "[a]", "-c:a", "pcm_s16le"]);
        inputs.push(f.input(name, &path, 30_000, false, true));
    }
    let rows = analyze(&f.ffmpeg, &inputs).unwrap();
    for (row, offset) in rows.iter().zip([2000i64, 6000]) {
        let (a, b) = marker(row, "intro");
        assert!((a - offset).abs() <= 500);
        assert!((b - offset - 16_000).abs() <= 500);
    }
    valid(&rows, 30_000);
}

#[test]
#[ignore = "generates rolling text using explicitly configured FFmpeg and TrueType font"]
fn rolling_end_text_is_detected_but_a_dark_scene_is_not() {
    let f = Fixture::new();
    let font = std::env::var("REX_TEST_FONT").expect("set REX_TEST_FONT to a real TrueType font");
    // Authored text is the generator's input, not detector output or a marker cue.
    let text = f.root.join("credits.txt");
    std::fs::write(&text, (0..60).map(|i| format!("{}\n", ["DIRECTOR NAME", "CAST AND CREW", "CAMERA TEAM", "SOUND DESIGN"][i % 4])).collect::<String>()).unwrap();
    let filter = format!("drawtext=fontfile='{}':textfile='{}':fontsize=20:fontcolor=white:line_spacing=8:x=(w-text_w)/2:y=h-32*(t-6)", font.replace('\\', "\\\\").replace(':', "\\:"), text.to_str().unwrap());
    let credits = f.generate("credits.mkv", &["-f", "lavfi", "-i", "color=black:s=384x216:r=16:d=32", "-vf", &filter]);
    let dark = f.generate("dark.mkv", &["-f", "lavfi", "-i", "color=black:s=384x216:r=16:d=32", "-vf", "drawbox=x=80+10*t:y=50:w=70:h=100:color=gray@0.3:t=fill"]);
    let mut inputs = vec![f.input("credits", &credits, 32_000, true, false), f.input("dark", &dark, 32_000, true, false)];
    for input in &mut inputs { input.group = None; }
    let rows = analyze(&f.ffmpeg, &inputs).unwrap();
    let (a, b) = marker(&rows[0], "credits");
    assert!((6000..=11_000).contains(&a), "rolling text starts at 6s, detected {a}");
    assert!(b >= 30_000, "rolling text should continue to end, detected {b}");
    assert!(rows[1].markers.is_empty(), "dark scenery is not credits");
    valid(&rows, 32_000);
}

#[test]
fn authored_chapter_bounds_are_preserved_and_malformed_ranges_rejected() {
    let input = analysis::Input { key: "source-id".into(), part_id: "part-id".into(), url: "unused".into(), auth: None,
        duration_ms: 50_000, video_index: None, audio_index: None, group: None,
        chapters: vec![json!({"title":"Opening", "startTimeOffset":1200,"endTimeOffset":12500}),
            json!({"title":"Credits", "startTimeOffset":40000,"endTimeOffset":60000})] };
    let rows = analyze(Path::new("/not-needed-for-authored-cues"), &[input]).unwrap();
    assert_eq!(marker(&rows[0], "intro"), (1200, 12500));
    assert_eq!(rows[0].markers.len(), 1);
}
